using UnityEngine;
namespace FashionFit {
 public sealed class RunwayMaterialLab:MonoBehaviour {
  FashionFitApp app;public int ProfileIndex{get;private set;}public bool ShowReadings=true;public bool HatMode{get;private set;}int sizeIndex=1;
  readonly float[] sizes={.88f,1f,1.10f};ElasticSurface SelectedHat(){foreach(var h in app.Showroom.Hats)if((h.IsHeld||h.IsBeingAdjusted)&&h.Elastic)return h.Elastic;var support=app.Showroom.HeadForTarget(app.Showroom.OutfitTarget);foreach(var h in app.Showroom.Hats)if(h.IsEquipped&&h.Elastic.Head==support)return h.Elastic;return null;}public string SizeLabel=>SelectedHat()?(SelectedHat().Size*100).ToString("F0")+"%":"Chưa đội nón";
  public void Initialize(FashionFitApp owner){app=owner;}
  public string TargetLabel=>app.Showroom.OutfitTarget==0?"Mẫu đi bộ":app.Showroom.OutfitTarget==1?"Mẫu pose nữ":"Mẫu pose nam";
  bool HasHeldHat(){foreach(var h in app.Showroom.Hats)if(h.IsHeld||h.IsBeingAdjusted)return true;return false;}
  public void ToggleFocus(){HatMode=!HatMode;app.Report(HatMode?"Đang đo nón của nhân vật chọn":"Đang đo trang phục của nhân vật chọn");}
  public void SelectProfile(int index){ProfileIndex=(index+MembraneMaterial.Presets.Length)%MembraneMaterial.Presets.Length;var material=MembraneMaterial.Presets[ProfileIndex];var activeSurface=FocusedSurface();var activePanel=FocusedPanel();if(activeSurface&&activeSurface.GrabCount>0)activeSurface.SetMaterial(material);else if(activePanel&&activePanel.GrabCount>0)activePanel.Material=material;else if(HatMode||HasHeldHat()){var support=app.Showroom.HeadForTarget(app.Showroom.OutfitTarget);foreach(var hat in app.Showroom.Hats)if(hat.IsHeld||hat.IsBeingAdjusted||(hat.IsEquipped&&hat.Elastic.Head==support))hat.Elastic.SetMaterial(material);}else if(app.LayerLab.Current)app.LayerLab.Current.SetMaterial(material);else if(app.Showroom.OutfitTarget==0)app.Wardrobe.SetMembraneMaterial(material);else app.PoseStudio.Wearables[app.Showroom.OutfitTarget-1].SetMaterial(material);app.Report(material.label+" · chỉ áp cho đối tượng đang chọn; chưa đo sức bền thật");}
  MembraneMaterial FocusedMaterial(){var panel=FocusedPanel();if(panel)return panel.Material;var surface=FocusedSurface();if(surface)return surface.Material;foreach(var hat in app.Showroom.Hats)if((hat.IsHeld||hat.IsBeingAdjusted)&&hat.Elastic)return hat.Elastic.Material;if(HatMode){var support=app.Showroom.HeadForTarget(app.Showroom.OutfitTarget);foreach(var hat in app.Showroom.Hats)if(hat.IsEquipped&&hat.Elastic&&hat.Elastic.Head==support)return hat.Elastic.Material;return null;}if(app.LayerLab.Current)return app.LayerLab.Current.Material;if(app.Showroom.OutfitTarget==0)return app.Wardrobe.ActiveMembraneMaterial;var pose=app.PoseStudio.Wearables[app.Showroom.OutfitTarget-1];return pose.Surface?pose.Surface.Material:null;}
  public string ProfileLabel=>FocusedMaterial()?.label??"Chọn mô hình đàn hồi";
  public void CycleProfile(){var current=FocusedMaterial();SelectProfile(System.Array.IndexOf(MembraneMaterial.Presets,current)+1);}

  public void CycleHatSize(){HatMode=true;var selectedHat=SelectedHat();if(!selectedHat){app.Report("Đội hoặc cầm nón trước khi chỉnh cỡ");return;}sizeIndex=0;for(int i=0;i<sizes.Length;i++)if(selectedHat.Size>=sizes[i]-.001f)sizeIndex=i+1;sizeIndex%=sizes.Length;var support=app.Showroom.HeadForTarget(app.Showroom.OutfitTarget);bool warning=false;foreach(var hat in app.Showroom.Hats)if(hat.Elastic==selectedHat){hat.Elastic.SetSize(sizes[sizeIndex]);hat.Elastic.Step(1f/60);warning|=hat.Elastic.OutsideLinearRange;}app.Report("Cỡ nón "+SizeLabel+(warning?" · vượt miền đàn hồi giả định, hãy tăng cỡ; chưa mô phỏng rách":" · nón nhỏ hơn đầu sẽ bị căng; Grip để tháo"));}
  static string ReadSurface(ElasticSurface s)=>s.ContactMotion&&s.ContactMotion.Active?s.ContactMotion.Summary:s.Reading.Summary+" · giới hạn thử "+(s.Material.pullTravelM*100).ToString("F1")+" cm · lực lệnh "+Mathf.Max(s.HandForce0.magnitude,s.HandForce1.magnitude).ToString("F1")+" N (ảo)"+(s.OutsideLinearRange?" · ngoài miền đàn hồi":"");
  public string Summary{get{foreach(var hat in app.Showroom.Hats)if((hat.IsHeld||hat.IsBeingAdjusted)&&hat.Elastic)return "Nón · "+ReadSurface(hat.Elastic);if(HatMode){var target=app.Showroom.HeadForTarget(app.Showroom.OutfitTarget);foreach(var hat in app.Showroom.Hats)if(hat.IsEquipped&&hat.Elastic&&hat.Elastic.Head==target)return "Nón · "+ReadSurface(hat.Elastic);return "Đội nón cho nhân vật chọn để đo độ căng";}if(app.LayerLab.Current)return app.LayerLab.Current.Summary;if(app.Showroom.OutfitTarget>0){var pose=app.PoseStudio.Wearables[app.Showroom.OutfitTarget-1];if(pose.Surface)return ReadSurface(pose.Surface);}return app.Wardrobe.MaterialReading.Summary;}}
  public void ResetShapes(){var selected=new System.Collections.Generic.List<ElasticSurface>();var target=app.Showroom.HeadForTarget(app.Showroom.OutfitTarget);bool hats=HatMode||HasHeldHat();if(hats)foreach(var hat in app.Showroom.Hats)if(hat.IsHeld||hat.IsBeingAdjusted||(hat.IsEquipped&&hat.Elastic.Head==target))selected.Add(hat.Elastic);app.Player.EndActiveGrab();if(hats){foreach(var surface in selected)surface.ResetShape();}else if(app.LayerLab.Current)app.LayerLab.Current.ResetDrape();else if(app.Showroom.OutfitTarget==0)app.Wardrobe.ResetCloth();else{var pose=app.PoseStudio.Wearables[app.Showroom.OutfitTarget-1];if(pose.Surface)pose.Surface.ResetShape();}app.Report("Đã đặt lại đối tượng chọn; nón đang đội vẫn tiếp xúc đầu");}
  public ElasticSurface FocusedSurface(){if(HasHeldHat())return SelectedHat();if(app.Player.Hands)for(int i=0;i<2;i++){var target=app.Player.Hands.HeldBy(i);if(target&&target.PickSurface)return target.PickSurface;}if(HatMode)return SelectedHat();var ao=app.LayerLab.Current;if(ao){if(ao.SelectedLayer==3)return ao.Pants.Surface;if(ao.SelectedLayer==0||ao.SelectedLayer<0)return ao.Bodice.Surface;return null;}if(app.Showroom.OutfitTarget>0)return app.PoseStudio.Wearables[app.Showroom.OutfitTarget-1].Surface;var shirt=app.Model.GetComponentInChildren<InteractiveShirt>();return shirt?shirt.Surface:null;}
  public LayeredPanel FocusedPanel(){if(HasHeldHat())return null;if(app.Player.Hands)for(int side=0;side<2;side++){var held=app.Player.Hands.HeldBy(side);if(held&&held.PickSurface)return null;}if(app.Player.Hands)for(int i=0;i<2;i++){var target=app.Player.Hands.HeldBy(i);if(target&&target.Panel)return target.Panel;}var ao=app.LayerLab.Current;return !ao?null:ao.SelectedLayer==1?ao.Front:ao.SelectedLayer==2?ao.Back:null;}
  public string DetailedReadout{get{var panel=FocusedPanel();var surface=panel?null:FocusedSurface();if(surface&&surface.ContactMotion&&surface.ContactMotion.Active)return surface.ContactMotion.Readout;return MaterialReadout.Format(panel?panel.Material:surface?surface.Material:FocusedMaterial(),panel?panel.Reading:surface?surface.Reading:app.Wardrobe.MaterialReading,surface,panel);}}
  public void Explain(){var surface=FocusedSurface();if(surface&&surface.ContactMotion&&surface.ContactMotion.Active){app.Report("Vải tự do giữ chiều dài nghỉ trên lưới mô phỏng; vị trí do Grip, trọng lực và tiếp xúc; bản thử chưa hiệu chuẩn lực hoặc giới hạn giãn");return;}app.Report("ε=(L−L0)/L0; T=E·h·ε (N/m). Khi thả: u(t)=u0·exp(−t/τ). Vải nén dùng độ cứng thấp hơn để mô tả nhăn; tham số E minh họa chưa hiệu chuẩn; chưa tính đứt/rách.");}
 }
}
